        "s_md": "Что добавить в CLAUDE.md", "s_new": "Новые способы использования", "s_hor": "Куда двигается твой воркфлоу",
        "tools": "Инструменты", "langs": "Языки (по правкам файлов)", "fix": "Фикс.",
        "st_msg": "сообщений", "st_ses": "сессий", "st_days": "активных дней", "st_tool": "вызовов тулзов",
        "st_edit": "правок", "st_file": "файлов", "st_tok": "тыс. токенов на выход", "st_mpd": "сообщений в день",
        "no_data": "нет данных", "no_fric": "заметного трения не найдено", "no_sugg": "нет предложений",
        "no_edit": "нет правок файлов", "period": "последние {n} дней",
        "foot": "Сгенерировано mentor · {ts} · часть оценок выведена моделью, читай их как гипотезу, а не приговор.",
    },
}


def ic(name, cls="ic"):
    return (f'<svg class="{cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
            f'stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" '
            f'aria-hidden="true">{ICONS.get(name, "")}</svg>')


